import { get, handleApiError, post } from '@helpers/httpClient';

import { mapClubToBack } from '../@mappers/clubs.toBack.mapper';
import { mapClubToFront } from '../@mappers/clubs.toFront.mapper';
import { IClubDTO, IGetClubsCriteria } from '../@types/clubs.dto.types';
import { IClub } from '../@types/clubs.types';

export const getClubsAsync = async (criteria: IGetClubsCriteria = { my: true }) => {
  const res = await get('/ajax/clubs/clubs_list.php', criteria).then<IClubDTO[]>(handleApiError);
  return res.map(mapClubToFront);
};

export const getOneClubAsync = async (id: number) => {
  const res = await get('/ajax/clubs/clubs_one.php', { id }).then(handleApiError);
  return mapClubToFront(res);
};
export const addOrEditClubAsync = async (data: IClub) => {
  const res = await post('/ajax/clubs/clubs_add_or_edit.php', mapClubToBack(data)).then(
    handleApiError,
  );
  return +res.id;
};
