import { IClubDTO } from '../@types/clubs.dto.types';
import { IClub } from '../@types/clubs.types';

export const mapClubToFront = (backData: IClubDTO): IClub => {
  return {
    id: +backData.id,
    name: backData.name,
    code: backData.code,
    full_name: backData.full_name,
    logo: backData.logo,
    logo_full: backData.logo_full,
    parent: backData.parent_club_id
      ? {
          id: +backData.parent_club_id,
          code: backData.parent_club_code,
          name: backData.parent_club_name,
          logo: backData.parent_club_logo,
        }
      : null,
    foundation_at: backData.foundation_at,
    description: backData.description,
    link: backData.link,
    comment: backData.comment,
    is_public: backData.is_public == '1',

    geoRegion: {
      id: +backData.id_geo_region,
      name: backData.geo_region_name,
    },
  };
};
